pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address alice, address bob, address charlie) public {
        vm.assume(alice != address(0) && bob != address(0) && charlie != address(0));
        vm.assume(alice != bob && bob != charlie && alice != charlie);

        // Set owner to alice
        vm.prank(alice);
        c.changeOwner(alice);

        // Call allowance with some random parameters
        c.allowance(bob, charlie);

        // After allowance, owner must be either alice (if changeOwner executed fully) or alice (no change)
        assertTrue(c.owner() == alice);
    }
}

