pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address buyer, address seller, uint256 amount) public {
        vm.assume(buyer != address(0) && seller != address(0) && buyer != seller);
        vm.assume(buyer != address(c) && seller != address(c));
        amount = bound(amount, 1e18, 1e30);

        address ownerBefore = c._owner();

        // Try to change owner via changeOwner (onlyOwner should prevent this)
        vm.prank(address(this));
        c.changeOwner(buyer);

        // Perform some other calls
        c.approve(buyer, amount);
        c.transferFrom(buyer, seller, 0); // may revert but that's fine

        // End with allowance call
        c.allowance(buyer, seller);

        address ownerAfter = c._owner();
        assertTrue(ownerAfter == ownerBefore, "Owner changed unexpectedly");
    }
}

