pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        // Check allowance as a way to drive the contract, though the property is about owner()
        // The property: if someone who is not the owner tries to call changeOwner, it should revert
        // But the bug makes owner() return address(0), so address(this) is not owner and address(0) is not owner
        // So the property is: for any caller that is not the owner, calling changeOwner should revert
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("changeOwner(address)", caller));
        assertTrue(!success, "changeOwner should revert when caller is not owner");
    }
}

